from collections import namedtuple
from taf.ul.ettf.msg_capture.comparison_presenter import ExceptionlessComparisonPresenter

MatcherData = namedtuple('MatcherData', ['id', 'name'])
Packet = namedtuple('Packet', ['id', 'data'])
Entry = namedtuple('Entry', ['matcher_data', 'packet', 'comparison_result'])


def provide_matcher_name(matcher):
    try:
        if hasattr(matcher, 'name') and matcher.name:
            return matcher.name
        if hasattr(matcher, 'get_name') and matcher.get_name():
            return matcher.get_name()
    except TypeError:
        pass
    try:
        return matcher.__name__
    except AttributeError:
        return matcher.__class__.__name__


class ComparisonRegistry(object):
    def __init__(self):
        self._history = []
        self._comparison_container_type = 'With order'
        self._log_callback = lambda m, p, r: self.log(m, p, r)

    @property
    def history(self):
        return self._history

    @property
    def log_callback(self):
        return self._log_callback

    def clear(self):
        self._history = []

    def log(self, matcher, packet, comparison_result):
        matcher_name = provide_matcher_name(matcher)

        self._history.append(Entry(
            MatcherData(id(matcher), matcher_name),
            Packet(id(packet), packet),
            comparison_result))

    def set_container_type(self, condition):
        self._comparison_container_type = provide_matcher_name(condition)

    def show(self):
        ExceptionlessComparisonPresenter().show(self.history, self._comparison_container_type)
